public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> result = new ArrayList<>();
    if (nums == null || nums.length == 0) {
        return result;
    }
    backtrace(nums, 0, new ArrayList<>(), result);
    return result;
}

private void backtrace(int[] nums, int start, List<Integer> path, List<List<Integer>> result) {
    if (path.size() == nums.length) {
        result.add(new ArrayList<>(path));
        return;
    }
    for (int i = start; i < nums.length; i++) {
        if (isUsed(nums, start, i)) {
            continue;
        }
        path.add(nums[i]);
        backtrace(nums, i + 1, path, result);
        path.remove(path.size() - 1);
    }
}

private boolean isUsed(int[] nums, int start, int end) {
    for (int i = start; i < start + end; i++) {
        if (nums[i] == nums[end]) {
            return true;
        }
    }
    return false;
}

public List<List<Integer>> permute(int[] nums) {
        List<List<Integer>> result = new ArrayList<>();
        if (nums == null || nums.length == 0) {
            return result;
        }
        helper(nums, 0, result);
        return result;
    }

private void helper(int[] nums, int start, List<List<Integer>> result) {
        if (start == nums.length) {
            result.add(new ArrayList<>(Arrays.asList(nums))); // Without the sublist copy, the list of lists will accumulate changes
            return;
        }
        for (int i = start; i < nums.length; i++) {
            swap(nums, start, i);
            helper(nums, start + 1, result);
            swap(nums, start, i); // Backtrack
        }
    }

private void swap(int[] nums, int i, int j) {
        int temp = nums[i];
        nums[i] = nums[j];
        nums[j] = temp;
    }

public List<List<Integer>> permute(int[] nums) {
        if (nums == null || nums.length == 0) {
            return Arrays.asList(new ArrayList<>());
        }

        List<List<Integer>> result = new ArrayList<>();
        permuteRecursive(nums, 0, result);
        return result;
    }

private void permuteRecursive(int[] nums, int index, List<List<Integer>> result) {
        if (index == nums.length) {
            result.add(new ArrayList<>(Arrays.asList(nums)));
            return;
        }

        for (int i = index; i < nums.length; i++) {
            swap(nums, index, i);
            permuteRecursive(nums, index + 1, result);
            swap(nums, index, i); // backtrack
        }
    }

private void swap(int[] nums, int i, int j) {
        int temp = nums[i];
        nums[i] = nums[j];
        nums[j] = temp;
    }

public List<List<Integer>> permute(int[] nums ) {
        ArrayList<List<Integer>> list = new ArrayList<List<Integer>>();
        permute(nums, 0, list);
        return list;
    }

private void permute(int[] nums, int idx, List<List<Integer>> list) {
        if(idx == nums.length) {
            List<Integer> temp = new ArrayList<>();
            for(int num : nums) {
                temp.add(num);
            }
            list.add(temp);
            return;
        }
        for(int i = idx; i < nums.length; i ++) {
            Collections.swap(nums, i , idx);
            permute(nums , idx+1, list);
            Collections.swap(nums, i, idx);
        }
    }

public int findLargestSubstring(List<String> strings) {
    // Sort the list of strings to have larger strings first
    strings.sort((a, b) -> b.length() - a.length());

    for (String str: strings) {
        for (int i = 0; i < str.length(); i++) {
            int start = i;
            StringBuilder reversedStr = new StringBuilder();
            while (start >= 0 && !Character.isDigit(str.charAt(start))) {
                reversedStr.append(str.charAt(start));
                start--;
            }
            if (reversedStr.length() > 0 && strings.contains(reversedStr.toString()) || strings.contains(str)) {
                return reversedStr.length();
            }
        }
    }
    return 0; // Return 0 if no valid substring is found
}

