    }

    int maxLength = 0;
    for (int i = 0; i < strings.size(); i++) {
        String current = strings.get(i);
        for (int j = 1; j <= current.length() / 2; j++) {
            String reversed = current.substring(0, j) + current.substring(j);
            if (strings.contains(reversed) || strings.contains(current)) {
                maxLength = Math.max(maxLength, reversed.length());
            }
        }
    }

    return maxLength;
}

