public static int countOilDeposits(char[][] grid) {
    int count = 0;
    for (int i = 0; i < grid.length; i++) {
        for (int j = 0; j < grid[i].length; j++) {
            if (grid[i][j] == '@') {
                count++;
                exploreOilDeposits(grid, i, j);
            }
        }
    }
    return count;
}

private static void exploreOilDeposits(char[][] grid, int x, int y) {
    if (x < 0 || x >= grid.length || y < 0 || y >= grid[0].length || grid[x][y] != '@') {
        return;
    }
    grid[x][y] = '*'; // Mark visited oil deposits
    exploreOilDeposits(grid, x + 1, y);
    exploreOilDeposits(grid, x - 1, y);
    exploreOilDeposits(grid, x, y + 1);
    exploreOilDeposits(grid, x, y - 1);
}

