public static int countOilDeposits(char[][] grid) {
    Set<Point> visited = new HashSet<>();
    int deposits = 0;

    for (int i = 0; i < grid.length; i++) {
        for (int j = 0; j < grid[0].length; j++) {
            if (grid[i][j] == '@' && !visited.contains(new Point(i, j))) {
                visited.add(new Point(i, j));
                dfs(grid, visited, i, j);
                deposits++;
            }
        }
    }

    return deposits;
}

private static boolean isValid(char[][] grid, Point point) {
    int x = point.x;
    int y = point.y;
    return x >= 0 && x < grid.length && y >= 0 && y < grid[0].length;
}

private static void dfs(char[][] grid, Set<Point> visited, int x, int y) {
    if (!isValid(grid, new Point(x, y))) {
        return;
    }

    if (grid[x][y] == '*') {
        return;
    }

    visited.add(new Point(x, y));
    grid[x][y] = '*';

    dfs(grid, visited, x + 1, y);
    dfs(grid, visited, x - 1, y);
    dfs(grid, visited, x, y + 1);
    dfs(grid, visited, x, y - 1);
}

public static int countOilDeposits(char[][] grid) {
    int rows = grid.length;
    int cols = rows > 0 ? grid[0].length : 0;
    int result = 0;

    // Used to mark each visited oil pocket
    BitSet visited = new BitSet(rows * cols);

    for (int r = 0; r < rows; r++) {
        for (int c = 0; c < cols; c++) {
            // If the current cell contains an oil pocket and it has not been visited
            if (grid[r][c] == '@' && !visited.get(r * cols + c)) {
                result++;
                // Perform a DFS to explore the entire oil pocket
                exploreOilPocket(grid, r, c, visited);
            }
        }
    }

    return result;
}

private static void exploreOilPocket(char[][] grid, int r, int c, BitSet visited) {
    // Mark the current cell as visited
    visited.set(r * grid[0].length + c);

    // Explore all adjacent cells
    for (int dr = -1; dr <= 1; dr++) {
        for (int dc = -1; dc <= 1; dc++) {
            int nr = r + dr;
            int nc = c + dc;

            // Check if the new cell is within bounds and contains an oil pocket
            if (nr >= 0 && nr < grid.length && nc >= 0 && nc < grid[0].length && grid[nr][nc] == '@') {
                // Recursively explore the new cell
                exploreOilPocket(grid, nr, nc, visited);
            }
        }
    }
}

public static int countOilDeposits(char[][] grid) throws Exception {
    int count = 0;
    oilMap = new int[grid.length][grid[0].length];

    // Iterate through each cell in the grid
    for (int x = 0; x < grid.length; x++) {
        for (int y = 0; y < grid[0].length; y++) {
            if (grid[x][y] == '@' && oilMap[x][y] == 0) {
                // Start an oil deposit search
                int oilCount = dfs(x, y);
                // If an oil deposit has been found, increment the count
                if (oilCount > 0) count++;
            }
        }
    }
    return count;
}

private static int dfs(int x, int y) {
    // Check if the current position is out of bounds or already visited
    if (x < 0 || x >= oilMap.length || y < 0 || y >= oilMap[0].length || oilMap[x][y] != 0) return 0;

    // Mark the current position as visited
    oilMap[x][y] = 1;

    // Explore all four possible directions (up, down, left, right)
    int deposits = dfs(x, y - 1) + dfs(x, y + 1) + dfs(x - 1, y) + dfs(x + 1, y);

    // Return the total number of oil deposits in the current path
    return deposits + 1;
}

