public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (n <= 0 || start == null || end == null || paths == null) {
        throw new IllegalArgumentException("Invalid input");
    }

    boolean[][] map = new boolean[n][n];
    for (int[] path : paths) {
        if (path.length != 2) {
            throw new IllegalArgumentException("Invalid path format");
        }
        int[] a = path[0];
        int[] b = path[1];
        if (!isValidCoordinates(a, b, n) || !isValidCoordinates(b, a, n)) {
            throw new IllegalArgumentException("Invalid path coordinates");
        }
        map[a[0]][a[1]] = true;
    }

    if (!isValidCoordinates(start[0], start[1], n) || !isValidCoordinates(end[0], end[1], n)) {
        throw new IllegalArgumentException("Invalid starting or ending coordinates");
    }

    boolean[] visited = new boolean[n * n];
    boolean[] pathTaken = new boolean[n * n];

    return canTravel(maze, start, end, n, visited, pathTaken) ? "can be travelled" : "cannot be travelled";
}

private static boolean canTravel(boolean[][] maze, int[] start, int[] end, int n, boolean[] visited, boolean[] pathTaken) {
    if (start[0] == end[0] && start[1] == end[1]) {
        return true;
    }

    visited[start[0]][start[1]] = true;
    pathTaken[start[0]][start[1]] = true;

    boolean[] north = { start[0] - 1, start[1] };
    boolean[] south = { start[0] + 1, start[1] };
    boolean[] east = { start[0], start[1] + 1 };
    boolean[] west = { start[0], start[1] - 1 };

    if (isValidCoordinates(north[0], north[1], n) && !visited[north[0]][north[1]]) {
        if (canTravel(maze, north, end, n, visited, pathTaken)) {
            return true;
        }
        pathTaken[north[0]][north[1]] = false;
    }

    if (isValidCoordinates(south[0], south[1], n) && !visited[south[0]][south[1]]) {
        if (canTravel(maze, south, end, n, visited, pathTaken)) {
            return true;
        }
        pathTaken[south[0]][south[1]] = false;
    }

    if (isValidCoordinates(east[0], east[1], n) && !visited[east[0]][east[1]]) {
        if (canTravel(maze, east, end, n, visited, pathTaken)) {
            return true;
        }
        pathTaken[east[0]][east[1]] = false;
    }

    if (isValidCoordinates(west[0], west[1], n) && !visited[west[0]][west[1]]) {
        if (canTravel(maze, west, end, n, visited, pathTaken)) {
            return true;
        }
        pathTaken[west[0]][west[1]] = false;
    }

    visited[start[0]][start[1]] = false;
    return false;
}

private static boolean isValidCoordinates(int x, int y, int n) {
    return x >= 0 && x < n && y >= 0 && y < n;
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Initialize the map to store paths between nodes
    Map<Integer, List<Integer>> adjacencyList = new HashMap<>();
    for (int[] path : paths) {
        adjacencyList.computeIfAbsent(path[0], k -> new ArrayList<>()).add(path[1]);
        adjacencyList.computeIfAbsent(path[1], k -> new ArrayList<>()).add(path[0]);
    }
    // Perform a depth-first search to check if the_path is valid
    boolean isPossible = doDFS(adjacencyList, start[0], start[1], end[0], end[1]);
    if (isPossible) return "can be travelled";
    else return "cannot be travelled";
}

private static boolean doDFS(Map<Integer, List<Integer>> adjacencyList, int start, int x, int y, int end) {
    // Check if the end node is reached
    if (x == end && y == end) return true;
    // Mark the starting point as visited
    for (int neighbor : adjacencyList.getOrDefault(start, new ArrayList<>())) {
        if (neighbor == end) return true;
        // Recursively search for the path through the neighbor
        List<Integer> neighbors = adjacencyList.getOrDefault(neighbor, new ArrayList<>());
        boolean isFound = doDFS(adjacencyList, neighbor, start, x, y);
        if (isFound) return true;
    }
    // If no path is found, mark the starting point as not visited
    return false;
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
        // Existence check
        if (paths == null || paths.length == 0 || start == null || end == null || start.length != 2 || end.length != 2) {
            throw new IllegalArgumentException("Invalid input");
        }

        // Generate all n-tersections
        List<List<Integer>> grid = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            List<Integer> row = new ArrayList<>();
            for (int j = 0; j < n; j++) {
                row.add(-1); // -1 indicates unvisited
            }
            grid.add(row);
        }

        // Find the index of the starting n-tersection
        int startX = start[0] - 1;
        int startY = start[1] - 1;

        // Find the index of the ending n-tersection
        int endX = end[0] - 1;
        int endY = end[1] - 1;

        // Mark the starting n-tersection as visited
        grid.get(startX).set(startY, 1);

        // Initialize a stack with the starting n-tersection
        Stack<int[]> stack = new Stack<>();
        stack.push(new int[]{startX, startY});

        // Perform depth-first search to find the ending n-tersection
        while (!stack.isEmpty()) {
            int[] current = stack.pop();
            if (current[0] == endX && current[1] == endY) {
                return "can be travelled";
            }
            int[] direction = getDirection(current, n);
            if (direction != null && grid.get(current[0] + direction[0]).get(current[1] + direction[1]) == -1) {
                grid.get(current[0] + direction[0]).set(current[1] + direction[1], 1);
                stack.push(new int[]{current[0] + direction[0], current[1] + direction[1]});
            }
        }

        // Not possible to travel
        return "cannot be travelled";
    }

private static int[] getDirection(int[] current, int n) {
        // Possible directions: up, down, left, right
        for (int i = -1; i <= 1; i++) {
            for (int j = -1; j <= 1; j++) {
                if (i == 0 && j == 0) continue; // Skip same direction
                if (current[0] + i >= 0 && current[0] + i < n && current[1] + j >= 0 && current[1] + j < n) {
                    for (int k = 0; k < paths.length; k++) {
                        int[] path = paths[k];
                        if (Arrays.equals(path, new int[]{current[0] + i, current[1] + j})) {
                            return new int[]{i, j};
                        }
                    }
                }
            }
        }
        return null;
    }

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (start == null || end == null || paths == null) {
        throw new IllegalArgumentException("Input arrays cannot be null");
    }
    if (start[0] < 0 || start[1] < 0 || start[0] >= n || start[1] >= n || end[0] < 0 || end[1] < 0 || end[0] >= n || end[1] >= n) {
        throw new IllegalArgumentException("Input coordinates are out of bounds");
    }
    int startX = start[0];
    int startY = start[1];
    int endX = end[0];
    int endY = end[1];

    boolean[][] visited = new boolean[n][n];
    Queue<int[]> queue = new LinkedList<>();

    visited[startX][startY] = true;
    queue.offer(new int[]{startX, startY});

    while (!queue.isEmpty()) {
        int[] current = queue.poll();
        for (int[] path : paths) {
            int nextX = current[0] + path[0];
            int nextY = current[1] + path[1];
            if (nextX >= 0 && nextX < n && nextY >= 0 && nextY < n && !visited[nextX][nextY] && current[0] != nextX && current[1] != nextY) {
                visited[nextX][nextY] = true;
                queue.offer(new int[]{nextX, nextY});
                if (nextX == endX && nextY == endY) {
                    return "can be travelled";
                }
            }
        }
    }
    return "cannot be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
