        int row = paths[i][0];
        int col = paths[i][1];
        visited[row][col] = true;
    }

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (i == start[0] && j == start[1]) {
                continue;
            }
            if (visited[i][j]) {
                continue;
            }

            boolean canTravel = true;
            for (int[] direction : directions) {
                int newRow = i + direction[0];
                int newCol = j + direction[1];

                if (newRow >= 0 && newRow < n && newCol >= 0 && newCol < n && !visited[newRow][newCol]) {
                    switch (paths[i][3 * n + 2 * (j - start[1])] {
                        case 0: // straight path
                            if (newRow != i || newCol != j) {
                                canTravel = false;
                                break;
                            }
                            break;
                        case 1: // right turn
                            if (newCol - j != 1) {
                                canTravel = false;
                                break;
                            }
                            break;
                        case 2: // left turn
                            if (j - newCol != 1) {
                                canTravel = false;
                                break;
                            }
                            break;
                        case 3: // Loop
                            // Implement loop handling if needed
                            break;
                        case 4: // Switch
                            // Implement switch handling if needed
                            break;
                        default: // Unknown path rule
                            // Handle unknown path rules
                            break;
                    }
                }

                if (!canTravel) {
                    break;
                }
            }

            if (canTravel) {
                return "can be travelled";
            }
        }
    }

    return "cannot be travelled";
}

public static String appx(String word1, String word2) {
    if (word1 == null || word2 == null || word1.isEmpty() || word2.isEmpty()) {
        throw new IllegalArgumentException("Inputs cannot be null or empty");
    }

    int commonCount = 0;
    for (char c1 : word1.toCharArray()) {
        for (char c2 : word2.toCharArray()) {
            if (c1 == c2) {
                commonCount++;
                break;
            }
        }
    }

    int length1 = word1.length();
    int length2 = word2.length();
    numerator = commonCount;
    denominator = length1 + length2;

    int gcd = findGCD(numerator, denominator);
    numerator /= gcd;
    denominator /= gcd;

    return "appx(" + word1 + ", " + word2 + ") = " + numerator + "/" + denominator;
}

private static int findGCD(int a, int b) {
    if (b == 0) {
        return a;
    }
    return findGCD(b, a % b);
}

public static String appx(String word1, String word2) {
        // Calculate the number of common letters
        int commonLetters = 0;
        for (int i = 0; i < word1.length(); i++) {
            for (int j = 0; j < word2.length(); j++) {
                if (word1.charAt(i) == word2.charAt(j)) {
                    commonLetters++;
                    break;
                }
            }
        }

        // Calculate the sum of the lengths of the two words
        int totalLength = word1.length() + word2.length();

        // Calculate the approximate value as a reduced fraction
        double approximateValue = (double) commonLetters / totalLength;
        return "appx(" + word1 + ", " + word2 + ") = " + commonLetters + "/" + Math.round(totalLength / commonLetters);
    }

public static String appx(String word1, String word2) {
    BigInteger num = BigInteger.ZERO;
    BigInteger den = BigInteger.ZERO;

    for (int i = 0; i < word1.length(); i++) {
        for (int j = 0; j < word2.length(); j++) {
            if (word1.charAt(i) == word2.charAt(j)) {
                num = num.add(BigInteger.valueOf(1));
            }
        }
    }

    BigInteger len1 = BigInteger.valueOf(word1.length());
    BigInteger len2 = BigInteger.valueOf(word2.length());
    den = len1.add(len2).subtract(num);

    return String.format("appx(%s, %s) = %s/%s", word1, word2, num.toString(), den.toString());
}

public static String appx(String word1, String word2) {
    if (word1 == null || word2 == null) {
        throw new IllegalArgumentException("Both words cannot be null");
    }

    String set1 = new HashSet<>(Arrays.asList(word1.toCharArray()));
    String set2 = new HashSet<>(Arrays.asList(word2.toCharArray()));
    set1.retainAll(set2);
    int commonLetters = set1.size();
    int totalLength = word1.length() + word2.length();
    double result = (double) commonLetters / totalLength;

    return String.format("appx(%s, %s) = %d/%d", word1, word2, (int) (result * totalLength), totalLength);
}

public static String appx(String word1, String word2) {
  long numCommon = 0;
  for (int i = 0; i < word1.length() && i < word2.length(); i++) {
    char c1 = word1.charAt(i);
    char c2 = word2.charAt(i);
    if (c1 == c2) {
      numCommon++;
    }
  }

  long numTotal = word1.length() + word2.length();
  long gcd = gcd(numCommon, numTotal);

  return String.format("appx(%s, %s) = %d/%d", word1, word2, numCommon / gcd, numTotal / gcd);
}

private static long gcd(long a, long b) {
  while (b != 0) {
    long temp = b;
    b = a % b;
    a = temp;
  }
  return a;
}

