public double trimMean(int[] arr) 
{
    if (arr == null || arr.length == 0)
    {
        throw new IllegalArgumentException("Array should not be null or empty");
    }

    int n = arr.length;
    int sortedArr[] = Arrays.copyOf(arr, n);
    Arrays.sort(sortedArr);

    double min = sortedArr[n / 20];
    double max = sortedArr[19 * n / 20];

    int trimmedArr[] = new int[n - 2];
    int trimmedIndex = 0;

    for (int i = 0; i < n; i++)
    {
        if (sortedArr[i] < min || sortedArr[i] > max)
        {
            trimmedArr[trimmedIndex++] = sortedArr[i];
        }
    }

    double mean = 0;
    for (int i = 0; i < trimmedArr.length; i++)
    {
        mean += trimmedArr[i];
    }

    return mean / trimmedArr.length;
}

