  double sum = 0;

  for (int i = start; i <= end; i++) {
    sum += arr[i];
  }

  return sum / (arr.length - start - end);
}

public boolean canArrange(int[] arr, int k) {
  Arrays.sort(arr);
  for (int i = 0, j = arr.length - 1; i < j; i++, j--) {
    if ((arr[i] % k + arr[j] % k) % k != 0) {
      return false;
    }
  }
  return true;
}

public boolean canArrange(int[] arr, int k) {
    // Count the frequency of each remainder when divided by k
    int[] remainders = new int[k];
    for (int num : arr) {
        remainders[num % k]++;
    }

    // Check if it's possible to pair the numbers
    int pairsCount = arr.length / 2;

    // Iterate through the remainders
    for (int i = 1; i <= k / 2; i++) {
        // Ensure the number of occurrences is even, or one of them is zero
        if ((remainders[i] * 2) < pairsCount && remainders[i] != remainders[k - i]) {
            return false;
        }
    }

    return true;
}

public boolean canArrange(int[] arr, int k) {
    int len = arr.length;
    if (len % 2 != 0) {
        return false;
    }
    Map<Integer, Integer> counts = new HashMap<>();
    for (int num : arr) {
        int mod = num % k;
        if (mod == 0) {
            counts.put(mod, counts.getOrDefault(mod, 0) + 1);
        } else {
            counts.put(k - mod, counts.getOrDefault(k - mod, 0) + 1);
        }
    }
    if (counts.getOrDefault(0, 0) % 2 != 0) {
        return false;
    }
    for (Map.Entry<Integer, Integer> entry : counts.entrySet()) {
        if (entry.getKey() != 0 && entry.getValue() % 2 != 0) {
            return false;
        }
    }
    return true;
}

public boolean canArrange(int[] arr, int k) {
    boolean[] visited = new boolean[k];
    int sum = 0;

    for (int num : arr) {
        sum += num % k;
        if (sum < 0)
            sum += k; // Adjust sum to fall within the range [0, k-1]
        visited[sum]++;
        sum %= k;
    }

    // Check pairs based on the visited array
    for (int i = 0; i < k; i++) {
        if (visited[i] > visited[k - i]) {
            return false; // Pair of (i, k-i) is not complete
        }
    }

    // Total number of pairs should be even for it to be possible
    return arr.length % 2 == 0;
}

public boolean canArrange(int[] arr, int k) {
    int[] frequency = new int[k];
    for (int num : arr) {
        if (num % k == 0) {
            frequency[0]++;
        } else {
            frequency[num % k]++;
        }
    }
    for (int i = 1; i < k / 2; i++) {
        if (frequency[i] != frequency[k - i]) {
            return false;
        }
    }
    return frequency[k / 2] % 2 == 0;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
        Map<Integer, List<Integer>> graph = new HashMap<>();
        for (int[] edge : edges) {
            int u = edge[0];
            int v = edge[1];
            graph.computeIfAbsent(u, k -> new ArrayList<>()).add(v);
            graph.computeIfAbsent(v, k -> new ArrayList<>()).add(u);
        }

        return dfs(0, -1, graph, hasApple);
    }

private int dfs(int current, int parent, Map<Integer, List<Integer>> graph, boolean[] hasApple) {
        int totalTime = 0;

        // Check if the current node has an apple
        if (hasApple[current]) totalTime += 2;

        // Recur for each child node
        for (int child : graph.getOrDefault(current, new ArrayList<>())) {
            if (child != parent) {
                totalTime += dfs(child, current, graph, hasApple);
            }
        }

        return totalTime;
    }

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    List<List<Integer>> graph = new ArrayList<>();
    for (int i = 0; i < n; i++) {
        graph.add(new ArrayList<>());
    }

    // Build the graph from edges
    for (int[] edge : edges) {
        int parent = edge[0], child = edge[1];
        graph.get(parent).add(child);
    }

    return dfs(0, -1, graph, hasApple);
}

private int dfs(int node, int parent, List<List<Integer>> graph, boolean[] hasApple) {
    int time = 0;

    // Traverse all children of the current node
    for (int child : graph.get(node)) {
        if (child == parent) {
            continue; // Skip the parent node
        }
        time += dfs(child, node, graph, hasApple);

        // If the child has an apple or the child is a common ancestor of the current node's apple and their parent
        if (hasApple[child] || (hasApple[parent] && child != parent)) {
            time += 2; // Adding 2 to account for the round trip
        }
    }

    return time;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
        Map<Integer, List<Integer>> graph = new HashMap<>();
        for (int[] edge : edges) {
            graph.computeIfAbsent(edge[0], k -> new ArrayList<>()).add(edge[1]);
            graph.computeIfAbsent(edge[1], k -> new ArrayList<>()).add(edge[0]);
        }

        Set<Integer> visited = new HashSet<>();
        visited.add(0);

        int pathCost = minTimeHelper(graph, visited, hasApple, 0, -1);

        return pathCost;
    }

private int minTimeHelper(Map<Integer, List<Integer>> graph, Set<Integer> visited, boolean[] hasApple, int currentNode, int parent) {
        int time = 0;
        for (int neighbor : graph.get(currentNode)) {
            if (neighbor == parent) continue;
            if (visited.contains(neighbor)) continue;
            visited.add(neighbor);
            int localTime = minTimeHelper(graph, visited, hasApple, neighbor, currentNode);
            if (localTime > 0 || hasApple[neighbor]) {
                time += 2 + localTime;
            }
        }
        return time;
    }

public int minTime(int n, int[][] edges, boolean[] hasApple) {
        Set<String> visited = new HashSet<>();
        return recurse(0, hasApple, visited);
    }

private int recurse(int i, boolean[] hasApple, Set<String> visited) {
        if (!visited.add(str(i))) {
            return 0;
        }
        int time = 0;
        for (int j = 0; j < edges.length; j++) {
            if (edges[j][0] == i) {
                time += recurse(edges[j][1], hasApple, visited);
            } else if (edges[j][1] == i) {
                time += recurse(edges[j][0], hasApple, visited);
            }
        }
        if (hasApple[i]) {
            time += 2;
        }
        visited.remove(str(i));
        return time;
    }

private String str(int i) {
        return i + "::" + hasApple[i];
    }

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Initialize a matrix to store the number of edges between each node
    int[][] matrix = new int[n][n];

    // Build the matrix based on the edges
    for (int[] edge : edges) {
        matrix[edge[0]][edge[1]] = 1;
        matrix[edge[1]][edge[0]] = 1;
    }

    // Perform DFS to find the minimum time
    return dfsEdToday(n, matrix, hasApple, 0);
}

private int dfsEdToday(int n, int[][] matrix, boolean[] hasApple, int node) {
    int time = 0;
    boolean hasAppleNode = hasApple[node];

    // Iterate through all neighbors of the current node
    for (int i = 0; i < n; i++) {
        if (matrix[node][i] == 1) {
            int childTime = dfsEdToday(n, matrix, hasApple, i);
            // Add the child time to the time if the child has an apple or it is a leaf node
            time += childTime == 0 && i != node && i != 0 ? 0 : childTime + 2;
            hasAppleNode = hasAppleNode || childTime > 0;
        }
    }

    // Return the time it takes to collect all apples starting from the current node
    return hasAppleNode ? time + 2 : time;
}

public String sortString(String s) {
    StringBuilder result = new StringBuilder();
    PriorityQueue<Character> minHeap = new PriorityQueue<>();
    PriorityQueue<Character> maxHeap = new PriorityQueue<>((a, b) -> b - a);

    // Build maxHeap
    for (char c : s.toCharArray()) {
        maxHeap.offer(c);
    }

    while (!minHeap.isEmpty() || !maxHeap.isEmpty()) {
        // Extract the smallest character from minHeap
        char minChar = minHeap.isEmpty() ? maxHeap.poll() : minHeap.poll();
        result.append(minChar);

        // Ensure the smallest character is not processed again
        while (!minHeap.isEmpty() && minHeap.peek() == minChar) {
            minHeap.poll();
        }

        // Extract the largest character from maxHeap
        char maxChar = maxHeap.isEmpty() ? minHeap.poll() : maxHeap.poll();
        result.append(maxChar);

        // Ensure the largest character is not processed again
        while (!maxHeap.isEmpty() && maxHeap.peek() == maxChar) {
            maxHeap.poll();
        }
    }

    return result.toString();
}

public String sortString(String s) {
    if (s == null || s.isEmpty()) {
        return s;
    }

    StringBuilder result = new StringBuilder();
    PriorityQueue<Character> minHeap = new PriorityQueue<>();
    PriorityQueue<Character> maxHeap = new PriorityQueue<>(Collections.reverseOrder());

    int[] counts = new int[26];
    for (char c : s.toCharArray()) {
        counts[c - 'A']++;
    }

    for (int i = 0; i < 26; i++) {
        if (counts[i] > 0) {
            minHeap.offer((char) ('A' + i));
            maxHeap.offer((char) ('A' + i));
        }
    }

    while (!minHeap.isEmpty() || !maxHeap.isEmpty()) {
        if (!minHeap.isEmpty()) {
            result.append(minHeap.poll());
            counts[minHeap.peek() - 'A']--;
            if (counts[minHeap.peek() - 'A'] > 0) {
                minHeap.offer(minHeap.poll());
            }
        }
        if (!maxHeap.isEmpty()) {
            result.append(maxHeap.poll());
            counts[maxHeap.peek() - 'A']--;
            if (counts[maxHeap.peek() - 'A'] > 0) {
                maxHeap.offer(maxHeap.poll());
            }
        }
    }

    return result.toString();
}

public String sortString(String s) {
