public String sortString(String s) {
    if (s == null || s.isEmpty()) {
        return s;
    }

    Map<Character, Integer> count = new HashMap<>();
    for (char ch : s.toCharArray()) {
        count.put(ch, count.getOrDefault(ch, 0) + 1);
    }

    StringBuilder result = new StringBuilder();
    PriorityQueue<Character> minHeap = new PriorityQueue<>((a, b) -> count.get(a) - count.get(b) == 0 ? a - b : count.get(a) - count.get(b));
    PriorityQueue<Character> maxHeap = new PriorityQueue<>((a, b) -> count.get(b) - count.get(a) == 0 ? b - a : count.get(b) - count.get(a));
    for (char ch : s.toCharArray()) {
        if (count.get(ch) == 1) {
            result.append(ch);
            count.put(ch, 0);
        } else {
            minHeap.offer(ch);
            maxHeap.offer(ch);
        }
    }

    while (result.length() < s.length()) {
        char minChar = minHeap.poll();
        while (count.get(minChar) > 0) {
            result.append(minChar);
            count.put(minChar, count.get(minChar) - 1);
        }
        char maxChar = maxHeap.poll();
        while (count.get(maxChar) > 0) {
            result.append(maxChar);
            count.put(maxChar, count.get(maxChar) - 1);
        }
    }

    return result.toString();
}

public boolean splitArraySameAverage(int[] nums) {
    int sum = 0;
    for (int num : nums) {
        sum += num;
    }
    int targetAverage = sum / nums.length;
    int[] secondHalf = nums;

    for (int i = 0; i < nums.length / 2; i++) {
        int temp = secondHalf[nums.length - i - 1];
        secondHalf[nums.length - i - 1] = secondHalf[i];
        secondHalf[i] = temp;
    }

    int sum1 = 0, sum2 = 0;
    for (int i = 0; i < nums.length / 2; i++) {
        sum1 += secondHalf[i];
        sum2 += nums[i];
    }

    if (sum1 == targetAverage && sum2 == targetAverage) {
        return true;
    } else {
        return false;
    }
}

public boolean splitArraySameAverage(int[] nums) {
        int n = nums.length;
        // Check edge case: array length must be greater than 2 to split an array equally
        if (n <= 2) {
            return false;
        }

        // Find the sum of all elements in the array
        int totalSum = Arrays.stream(nums).sum();
        // Calculate the average of the array elements
        double average = (double) totalSum / n;

        // Check if there is the same integer that evenly divides the total sum
        // Note: The average is an integer, so we need to check if there is an integer factor
        // The average of two non-empty arrays will be the average of their sums divided by their lengths
        // So, we need to check if there is an integer factor of the total sum
        // that is one-third of the total sum (since there are n-2 elements in both arrays)
        for (int i = 1; i <= n - 2; i++) {
            if (totalSum % i == 0 && totalSum / i == average * (n - 2)) {
                return true;
            }
        }

        return false;
    }

public boolean splitArraySameAverage(int[] nums) {
        if (nums == null || nums.length <= 1) {
            return false; // Cannot split into two non-empty arrays
        }

        int targetSum = sum(nums) / 2; // Calculate the target sum for each half

        // Check if the total sum is even
        if (totalSum % 2 != 0) {
            return false;
        }

        // Iterate through all possible starting points for the first half
        for (int start = 0; start < nums.length - 1; start++) {
            int leftSum = 0;
            for (int i = start; i < Math.min(start + totalSum / 2, nums.length); i++) {
                leftSum += nums[i];
            }
            // Check if the remaining sum can match the left half
            if (leftSum == targetSum) {
                // Check if the remaining elements can form the right half
                return !Arrays.stream(nums).skip(start + 1).anyMatch(num -> num == targetSum - leftSum);

            }
        }
        return false;
    }

private static int sum(int[] nums) {
        int totalSum = 0;
        for (int num : nums) {
            totalSum += num;
        }
        return totalSum;
    }

public boolean splitArraySameAverage(int[] nums) {
    if (nums == null || nums.length < 2) {
        return false;
    }
    int sum = Arrays.stream(nums).sum();
    double targetAverage = (double) sum / nums.length;
    Arrays.sort(nums);

    int startIndex = 0;
    for (int i = 1; i <= nums.length / 2; i++) {
        int endIndex = nums.length - i;
        if (nums[startIndex] * i == targetAverage && nums[endIndex] * i == targetAverage) {
            return true;
        } else {
            startIndex++;
        }
    }
    return false;
}

public boolean splitArraySameAverage(int[] nums) {
        if (nums.length <= 1) return false;

        // Calculate the total sum and size of the array
        int totalSum = Arrays.stream(nums).sum();
        int size = nums.length;

        // Iterate to find if there exists a subarray with equal sum
        for (int i = 0; i < size; i++) {
            int leftSum = nums[i];
            for (int j = i + 1; j < size; j++) {
                leftSum += nums[j];

                // Check if the right subarray sum equals the left subarray sum
                if (leftSum == totalSum / 2) return true;
            }
        }

        // If no such subarray is found, return false
        return false;
    }

public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length == 0) {
        throw new IllegalArgumentException("Cost array is null or empty");
    }

    if (cost.length < 2) {
        return cost[0]; // Only one step or no steps to climb
    }

    int[] minCosts = new int[cost.length];
    minCosts[0] = cost[0];
    minCosts[1] = cost[1];

    for (int i = 2; i < cost.length; i++) {
        minCosts[i] = Math.min(minCosts[i - 2], minCosts[i - 1]) + cost[i];
    }

    return Math.min(minCosts[cost.length - 2], minCosts[cost.length - 1]);
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length == 0) return 0;

    int n = cost.length;
    int[] dp = new int[n];

    dp[0] = cost[0];
    dp[1] = cost[1];

    for (int i = 2; i < n; i++) {
        dp[i] = Math.min(dp[i - 1], dp[i - 2]) + cost[i];
    }

    return Math.min(dp[n - 1], dp[n - 2]);
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length <= 2) {
        return cost.length == 0 ? 0 : Math.min(cost[0], cost[1]);
    }

    return Math.min(minCostClimbingStairs(cost, cost.length - 1), minCostClimbingStairs(cost, cost.length - 2)) + cost[cost.length - 1];
}

private int minCostClimbingStairs(int[] cost, int index) {
    if (index < 0) {
        return Integer.MAX_VALUE;
    }

    if (index == 0) {
        return cost[0];
    }

    return Math.min(minCostClimbingStairs(cost, index - 1), minCostClimbingStairs(cost, index - 2)) + cost[index];
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length == 0) {
        throw new IllegalArgumentException("Input array cannot be null or empty.");
    }

    int n = cost.length;
    int[] dp = new int[n + 1];
    dp[0] = 0;
    dp[1] = 0;

    for (int i = 2; i <= n; i++) {
        dp[i] = Math.min(dp[i - 1] + cost[i - 1], dp[i - 2] + cost[i - 2]);
    }

    return dp[n];
}

public int minCostClimbingStairs(int[] cost) {
    int[] dp = new int[cost.length];
    for (int i = 2; i < cost.length; i++) {
        dp[i] = Math.min(dp[i - 1] + cost[i - 1], dp[i - 2] + cost[i - 2]);
    }
    return Math.min(dp[cost.length - 1], dp[cost.length - 2]);
}

