public boolean hasAllCodes(String s, int k) {
    Set<String> set = new HashSet<>();
    for(int i = 0; i + k <= s.length(); i++){
        set.add(s.substring(i, i + k));// add substring to set
    }
    int num = 1<<k;// calculate the number of possible binary strings of length k
    return set.size() == num;// return true if the set size is equal to the number of possible binary strings of length k
}

public boolean hasAllCodes(String s, int k) {
    HashSet<String> set = new HashSet<>();
    for (int i = 0; i <= s.length() - k; i++) {
        set.add(s.substring(i, i + k));
    }
    return set.size() == (1 << k);
}

public boolean hasAllCodes(String s, int k) {
        Set<String> seen = new HashSet<>();
        int n = s.length() - k + 1;
        for (int i = 0; i < n; i++) {
            String subString = s.substring(i, i + k);
            if (seen.contains(subString)) {
                return false;
            }
            seen.add(subString);
        }
        return true;
    }

public boolean hasAllCodes(String s, int k) {
    if (k > s.length()) return false;
    Maps<intByte, Boolean> words = Maps.newHashMap();
    int wordCount = 0;

    for (int i = 0; i <= s.length() - k; ++i) {
        var data = s.charAt(i);
        int index = ((data << k) | (wordCount >>> 8)) >> 8;
        if (words.containsKey(index)) {
            return false;
        }
        words.put(index, true);
        wordCount += 0xff;
    }

    return true;
}

private static int requiredSizeFromCount(int count) {
