}

public boolean hasAllCodes(String s, int k) {
    Set<String> substringHashSet = new HashSet<>();
    int lastSubstringStart = 0;
    while (lastSubstringStart + k <= s.length()) {
        substringHashSet.add(s.substring(lastSubstringStart, lastSubstringStart + k));
        lastSubstringStart++;
    }
    return lastSubstringStart == s.length() && substringHashSet.size() == Math.pow(2, k);
}

