public int minInsertions(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }

    Stack<Character> stack = new Stack<>();
    int insertions = 0;

    for (char c : s.toCharArray()) {
        if (c == '(') {
            stack.push(c);
        } else {
            if (!stack.isEmpty()) {
                stack.pop();
            } else {
                insertions++;
            }
        }
    }

    insertions += stack.size() * 2;

    return insertions;
}

public int minInsertions(String s) {
        int res = 0, balance = 0;
        Deque<Character> stack = new ArrayDeque<>();

        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c == '(') {
                stack.push(c);
                balance++;
            } else {
                if (stack.isEmpty()) {
                    balance++; // Insert a '(' first
                    res++;
                } else {
                    stack.pop();
                    if (balance > 0) {
                        balance--; // Close the last '('
                    } else {
                        res++; // Insert a ')' after the last '('
                    }
                }
            }
        }

        // Close all remaining '(' with ')' before inserting them to balance the right brackets
        while (!stack.isEmpty()) {
            balance--;
            res++;
        }

        return res;
    }

