public int maxAbsoluteSum(int[] nums) {
    if (null == nums || nums.length <= 0) {
        throw new IllegalArgumentException("Input array must not be null or empty");
    }

    int maxSum = nums[0];
    int minSum = nums[0];
    int maxAbsoluteSum = nums[0];

    for (int i = 1; i < nums.length; i++) {
        if (nums[i] > 0) {
            maxSum += nums[i];
            minSum = Math.min(minSum + nums[i], nums[i]);
        } else {
            maxSum = Math.max(maxSum + nums[i], nums[i]);
            minSum = Math.min(minSum + nums[i], nums[i]);
        }
        maxAbsoluteSum = Math.max(maxAbsoluteSum, Math.max(maxSum, -minSum));
    }
    return maxAbsoluteSum;
}

public int maxAbsoluteSum(int[] nums) {
    int n = nums.length;
    if (n == 0) {
        return 0; // Edge case: empty array
    }

    int maxSum = nums[0];
    int minSum = nums[0];
    int maxAbsolute = 0;

    for (int i = 1; i < n; i++) {
        int currentSum = nums[i] + Math.max(maxSum, 0); // Update maxSum to include current element or restart at 0
        maxSum = Math.max(maxSum, nums[i]); // Update overall max sum if larger
        minSum = Math.min(minSum, nums[i] + Math.min(minSum, 0)); // Update minSum to include current element or restart at 0
        maxAbsolute = Math.max(maxAbsolute, Math.max(maxSum, -minSum)); // Update maxAbsolute to be the maximum of maxSum or -minSum
    }

    return maxAbsolute;
}

