public int findMinFibonacciNumbers(int k) {
    ArrayList<Integer> fib = new ArrayList<>();
    int i = 1, j = 1;
    fib.add(i);
    fib.add(j);
    int next = fib.get(i) + fib.get(j);
    while (next <= k) {
        fib.add(next);
        i = j;
        j = next;
        next = fib.get(i) + fib.get(j);
    }

    int result = 0;
    while (k > 0) {
        result++;
        int index = bisectRight(fib, k);
        k -= fib.get(index);
    }

    return result;
}

public int bisectRight(ArrayList<Integer> arr, int x) {
    int low = 0, high = arr.size() - 1;
    while (low <= high) {
        int mid = low + ((high - low) / 2);
        if (arr.get(mid) == x) {
            return mid;
        } else if (arr.get(mid) < x) {
            low = mid + 1;
        } else {
            high = mid - 1;
        }
    }
    return high;
}

public int findMinFibonacciNumbers(int k) {
    List<Integer> fibs = new ArrayList<>();
    fibs.add(1);
    fibs.add(1);
    fibs.add(2);
    while (true) {
        int next = fibs.get(fibs.size() - 1) + fibs.get(fibs.size() - 2);
        if (next > k) {
            break;
        }
        fibs.add(next);
    }
    int count = 0;
    while (k > 0) {
        int index = fibs.indexOf(k);
        if (index != -1) {
            k -= fibs.get(index);
            count++;
        } else {
            k -= fibs.get(fibs.size() - 2);
            fibs.remove(fibs.size() - 2);
        }
    }
    return count;
}

