        fibs.add(fibs.get(fibs.size() - 1) + fibs.get(fibs.size() - 2));
    }

    int minCount = 0;
    for (int i = fibs.size() - 1; i >= 0 && k > 0; i--) {
        while (k >= fibs.get(i)) {
            k -= fibs.get(i);
            minCount++;
        }
    }

    return minCount;
}

