public String makeGood(String s) {
    StringBuilder sb = new StringBuilder();
    int len = s.length();
    for(int i = 0; i < len ; i++){
        int j = i+1;
        while(j < len && !isGood(s.charAt(i), s.charAt(j))){
            j++;
        }
        i = j;
        while(j < len && isGood(s.charAt(i), s.charAt(j))){
            sb.append(s.charAt(j));
            j++;
        }
    }
    return sb.toString();
}

private boolean isGood(char i, char j){
    return i==j-32 || j==i+32;
}

public String makeGood(String s) {
        if (s == null || s.length() <= 1) {
            return s;
        }

        int len = s.length();
        StringBuilder sb = new StringBuilder(len);

        for (int i = 0; i < len - 1; i++) {
            if (Math.abs(s.charAt(i) - s.charAt(i + 1)) == 32) {
                // If characters are out of order, skip them
                continue;
            }
            sb.append(s.charAt(i));
        }

        // Append the last character if it's not part of a pair
        if (len > 1 && Math.abs(s.charAt(len - 1) - s.charAt(len - 2)) != 32) {
            sb.append(s.charAt(len - 1));
        }

        return sb.toString();
    }

public String makeGood(String s) {
    int pointer = 0;
    while (pointer < s.length() - 1) {
        char c1 = s.charAt(pointer);
        char c2 = s.charAt(pointer + 1);
        if (Math.abs(c1 - c2) == 32) {
            s = s.substring(0, pointer) + s.substring(pointer + 2);
            pointer = Math.max(0, pointer - 1); // need to check again, as we removed one char
        } else {
            pointer++;
        }
    }
    return s;
}

public String makeGood(String s) {
