    int i = 0;
    while (i < s.length()) {
        if (s.charAt(i) >= 'a' && s.charAt(i) <= 'z' && sb.length() > 0 && sb.charAt(sb.length() - 1) >= 'A' && sb.charAt(sb.length() - 1) <= 'Z' && s.charAt(i) == sb.charAt(sb.length() - 1) + 32) {
            sb.deleteCharAt(sb.length() - 1);
        } else {
            sb.append(s.charAt(i));
        }
        i++;
    }
    return sb.toString();
}

public String makeGood(String s) {
    var charStack = new ArrayDeque<Character>();
    for (char c : s.toCharArray()) {
        if (!charStack.isEmpty() && Math.abs(charStack.peek() - c) == 32) {
            charStack.pop();
        } else {
            charStack.push(c);
        }
    }
    return new String(charStack.toArray(new Character[0]));
}

public int maxUniqueSplit(String s) {
        if (s == null || s.isEmpty()) {
            return 0;
        }

        Set<String> seen = new HashSet<>();
        return maxUniqueSplitHelper(s, seen);
    }

private int maxUniqueSplitHelper(String s, Set<String> seen) {
        if (s.isEmpty()) {
            return seen.size();
        }

        char[] chars = s.toCharArray();
        int maxLength = 0;

        for (int i = 0; i < chars.length; i++) {
            for (int j = i + 1; j <= chars.length; j++) {
                String substring = s.substring(i, j);
                if (!seen.contains(substring)) {
                    seen.add(substring);
                    maxLength = Math.max(maxLength, maxUniqueSplitHelper(s.substring(j), seen));
                    seen.remove(substring);
                }
            }
        }

        return maxLength;
    }

public int maxUniqueSplit(String s) {
    int maxUnique = 0;

    if (s == null || s.isEmpty()) {
        return maxUnique;
    }

   visit recursively(s, 0, "", maxUnique);

    return maxUnique;
}

private void visit(String s, int start, String sub, int maxUnique) {
    if (start == s.length()) {
        maxUnique = Math.max(maxUnique, sub.length() / 2); // Each substring must be unique
        return;
    }

    if (sub.length() > 0 && !sub.equals(sub.substring(0, 2))) {
        ++maxUnique;
    }

    for (int end = start; end < s.length(); end++) {
        String newSub = sub + s.charAt(end);
        visit(s, end + 1, newSub, maxUnique);
    }
}

