    int splitCount = 0;
    List<String> currentSubstrings = new ArrayList<>();

    for (int i = 0; i <= s.length(); i++) {
        String currentSubstring = s.substring(0, i);
        if (!currentSubstrings.contains(currentSubstring)) {
            currentSubstrings.add(currentSubstring);
            splitCount++;
        } else if (currentSubstring.charAt(0) == s.charAt(i)) {
            // If the current substring is a prefix of the next character, skip it
            continue;
        } else {
            // If the current substring is a prefix and it skips over a different character, create a new substring
            currentSubstrings.add(currentSubstring);
            splitCount++;
        }
    }

    return splitCount;
}

