public String getSmallestString(int n, int k) {
    if (n <= 0 || k <= 0) {
        throw new IllegalArgumentException("Inputs n and k must be positive integers.");
    }

    StringBuilder result = new StringBuilder(n);
    int value = 0;

    // Fill the string with the smallest possible characters
    for (int i = 0; i < n; i++) {
        int possibleChar = minIvalue(value, k);
        result.append((char) ('a' + possibleChar));
        value += possibleChar;
        k -= possibleChar;
    }

    return result.toString();
}

private int minIvalue(int value, int k) {
    return Math.min(Math.floor(k / (n - value)), 25);
}

