        return null; // Return null if k is too large
    }
    // Construct the smallest string starting from 'a' and continuously adding 'a' until the value K is met
    for (int i = 0; i < n; ++i) {
        char currentChar = 'a';
        while (true) {
            char newValue = (char)(currentChar + 1);
            int newValueValue = newValue - 'a' + 1;
            if (k - newValueValue < 0) {
                break;
            }
            k -= newValueValue;
            currentChar = newValue;
        }
        smallestString.append(currentChar);
    }
    return smallestString.toString();
}

public String getSmallestString(int n, int k) {
    if (n <= 0 || k <= 0) {
        throw new IllegalArgumentException("Both n and k must be positive integers.");
    }

    StringBuilder smallestString = new StringBuilder();
    char[] alphabet = "abcdefghijklmnopqrstuvwxyz".toCharArray();
    int cnt = 0;

    for (int i = 0; i < n; i++) {
        if (cnt + i * (i + 1) > k) {
            smallestString.insert(0, 'a');
            k -= i * (i + 1);
        } else {
            smallestString.insert(0, alphabet[k % 26]);
            k -= k % 26;
        }
        cnt++;
    }

    return smallestString.toString();
}

public static double calculateProbability(int n) {
    if (n <= 1) {
        return 1.0;
    }
    double[] probabilities = new double[n + 1];
    probabilities[0] = 1.0;
    probabilities[1] = 1.0;
    probabilities[2] = 0.5;
    for (int i = 3; i <= n; i++) {
        probabilities[i] = (i - 1) * ((probabilities[i - 1] + probabilities[i - 2]) / 2);
    }
    return probabilities[n];
}

public static double calculateProbability(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("n must be a positive integer.");
    }
    // Save all previous computed probabilities to avoid redundant calculations
    double[] probabilities = new double[n + 1];
    for (int i = 1; i <= n; i++) {
        if (i == 1) {
            probabilities[i] = 1.0;
        } else if (i <= 3) {
            probabilities[i] = 1.0 / i;
        } else {
            probabilities[i] = 1.0 - probabilities[i - 1];
        }
    }
    return probabilities[n];
}

public static double calculateProbability(int n) {
    if (n == 0) {
