    }
    if (n == 1) {
        return 1.0;
    }
    if (n == 2) {
        return 0.5;
    }

    double probability = 1.0 / n;

    for (int i = 3; i <= n; i++) {
        probability *= 1.0 - 1.0 / i;
    }

    return probability;
}

public static double calculateProbability(int n) {
  if (n <= 2) {
    return 1.0;
  }
  if (n > Integer.MAX_VALUE / 2) {
    throw new IllegalArgumentException("Input exceeds the maximum allowed value");
  }

  double result = 1.0;
  for (int i = 2; i <= n; i++) {
    result = (result + 1 / i) / n;
  }

  return result;
}

public static double calculateProbability(int n) {
    if (n <= 1) {
        return 1.00000;
    }

    double[][] dp = new double[n + 1][n + 1];
    for (int i = 0; i <= n; i++) {
        dp[i][0] = 1.0 / i;
        if (i >= 2) {
            dp[i][i] = 1.0 / i;
            for (int j = 1; j < i; j++) {
                dp[i][j] = (dp[i - 1][j - 1] + dp[i - 1][j]) / i;
            }
        }
    }

    return dp[n][n - 1];
}

