        throw new IllegalArgumentException("Input array cannot be null or empty");
    }

    int uniqueNumber = 0;
    for (int num : nums) {
        uniqueNumber = (uniqueNumber ^ num) & ~uniqueNumber;
    }

    if (uniqueNumber == 0) {
        for (int num : nums) {
            if (uniqueNumber == num) return num;
