    }

    int[] count = new int[32];
    for (int num : nums) {
        for (int i = 0; i < 32; i++) {
            count[i] += num & 1;
            num >>>= 1;
        }
    }

    int result = 0;
    for (int i = 31; i >= 0; i--) {
        if (count[i] % 3 == 1) {
            result |= 1 << i;
        }
    }

    return result;
}

public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();

    // Special cases for low and high
    if (low == 0) result.add(low);
    if (high < 0) return result;
    if (high >= 10) high = 9; // Upper bound can maximum be 9

    // Start with single digits
    for (int i = 0; i <= 9; i++) {
        deepSearch(result, i, low, high);
    }

    return result;
}

private static void deepSearch(List<Integer> result, int current, int low, int high) {
    if (current >= low && current <= high) {
        result.add(current);
    }

    // Generate next possible numbers
    for (int i = -1; i <= 1; i++) {
        int next = current * 10 + (current + i);
        if (next >= low && next <= high) {
            deepSearch(result, next, low, high);
        }
    }
}

public static List<Integer> findSteppingNumbers(int low, int high) {
        List<Integer> steppingNumbers = new ArrayList<>();
        if (low > high) {
            return steppingNumbers;
        }

        steppingNumbers.add(0);
        steppingNumbers.add(1);
        steppingNumbers.add(2);

        for (int size = 2; steppingNumbers.size() <= (high + 1); size++) {
            List<Integer> newNumbers = new ArrayList<>();
            for (int number : steppingNumbers) {
                if (isSteppingNumber(number, size, low, high)) {
                    newNumbers.add(number);
                }
            }
            steppingNumbers = newNumbers.stream().distinct().collect(Collectors.toList());
        }

        return steppingNumbers.stream().sorted().collect(Collectors.toList());
    }

private static boolean isSteppingNumber(int number, int size, int low, int high) {
        String numStr = Integer.toString(number);
        if (numStr.length() != size) return false;

        for (int i = 0; i < size - 1; i++) {
            int currentDigit = Character.getNumericValue(numStr.charAt(i));
            int nextDigit = Character.getNumericValue(numStr.charAt(i + 1));
            if (Math.abs(currentDigit - nextDigit) != 1) return false;
        }

        return Integer.parseInt(numStr) >= low && Integer.parseInt(numStr) <= high;
    }

public static List<Integer> findSteppingNumbers(int low, int high) {
        List<Integer> steppingNumbers = new ArrayList<>();
        for (int num = low; num <= high; num++) {
            if (isSteppingNumber(num)) {
                steppingNumbers.add(num);
            }
        }

        steppingNumbers.sort(Integer::compareTo);
        return steppingNumbers;
    }

private static boolean isSteppingNumber(int num) {
        if (num == 0 || num == 10) {
            return true;
        }

        String numStr = String.valueOf(num);
        for (int i = 1; i < numStr.length(); i++) {
            int currentDigit = Character.digit(numStr.charAt(i), 10);
            int previousDigit = Character.digit(numStr.charAt(i - 1), 10);

            if ((currentDigit == previousDigit + 1 || currentDigit == previousDigit - 1) && (i < numStr.length() - 1 && (Character.digit(numStr.charAt(i + 1), 10) == currentDigit + 1 || Character.digit(numStr.charAt(i + 1), 10) == currentDigit - 1) || (i >= numStr.length() - 2))) {
                continue;
            } else {
                return false;
            }
        }

        return true;
    }

public static List<Integer> findSteppingNumbers(int low, int high) {
        List<Integer> steppingNumbers = new ArrayList<>();
        for (int i = low; i <= high; i++) {
            if (isValidSteppingNumber(i)) {
                steppingNumbers.add(i);
            }
        }
        Collections.sort(steppingNumbers);
        return steppingNumbers;
    }

private static boolean isValidSteppingNumber(int num) {
        String numStr = String.valueOf(num);
        for (int i = 1; i < numStr.length(); i++) {
            if (!Character.isDigit(numStr.charAt(i)) || !isSteppingAdjacent(numStr.charAt(i - 1), numStr.charAt(i))) {
                return false;
            }
        }
        return true;
    }

private static boolean isSteppingAdjacent(char currentDigit, char nextDigit) {
        return Math.abs(currentDigit - nextDigit) == 1;
    }

public static List<Integer> findSteppingNumbers(int low, int high) {
        List<Integer> steppingNumbers = new ArrayList<>();
        processNumbers(0, low, high, steppingNumbers);
        processNumbers(1, low, high, steppingNumbers);
        processNumbers(2, low, high, steppingNumbers);
        processNumbers(3, low, high, steppingNumbers);
        processNumbers(4, low, high, steppingNumbers);
        processNumbers(5, low, high, steppingNumbers);
        processNumbers(6, low, high, steppingNumbers);
        processNumbers(7, low, high, steppingNumbers);
        processNumbers(8, low, high, steppingNumbers);
        processNumbers(9, low, high, steppingNumbers);
        return steppingNumbers;
    }

private static void processNumbers(int digit, int low, int high, List<Integer> steppingNumbers) {
        if (digit >= 0 && digit <= 9) {
            int nextLow = Math.max(digit, low);
            int nextHigh = Math.min(9, digit);
            if (nextLow <= high) {
                steppingNumbers.add(digit);
                processNumbers(digit + 1, nextLow, high, steppingNumbers);
                processNumbers(digit - 1, nextLow, high, steppingNumbers);
            }
        }
    }

public static int countDigitOne(int n) {
    if (n < 0) {
        throw new IllegalArgumentException("Input must be a non-negative integer");
    }

    int count = 0;
    int k = 1;
    while (n >= k) {
        int digit = n / k % 10;
        int offset = n % k;

        count += (digit == 1) ? offset + 1 : k;

        k *= 10;
    }

    return count;
}

public static int countDigitOne(int n) {
    if (n < 0) {
        throw new IllegalArgumentException("Input must be a non-negative integer.");
    }

    if (n == 0) {
        return 0;
    }

    int digits = 0;
    int hundreds, tens = 0, ones;

    for (int i = 1; i <= n; i *= 10) {
        hundred = i / 100;
        tens = (i / 10) % 10;
        ones = i % 10;

        digits += hundred * i / 100;
        digits += (hundred + 1) * (tens / 10) * 10;
        digits += (hundred + 1) * tens / 10 + ones;
    }

    return digits;
}

