public static int countDigitOne(int n) {
    int count = 0;
    for (int i = 1; i <= n; i++) {
        int tmp = i, len = 0;
        while (tmp > 0) {
            len++;
            tmp /= 10;
        }
        int res = 0;
        tmp = i;
        for (int j = 1; j <= len; j++) {
            if (j > 1) {
                res += tmp / (int) Math.pow(10, j - 1);
            }
            int digit = tmp % (int) Math.pow(10, j - 1);
            if (digit == 1) {
                res += i % (int) Math.pow(10, j - 1) + 1;
            }
            tmp /= 10;
        }
        count += res;
    }
    return count;
}

public static int countDigitOne(int n) {
    if (n < 0) {
        throw new IllegalArgumentException("Input must be a non-negative integer");
    }

    int count = 0;
    for (int i = 1; i <= n; i++) {
        count += countDigitOneRecursive(i, 1);
    }
    return count;
}

private static int countDigitOneRecursive(int number, int currentDigit) {
    if (number == 0) {
        return 0;
    }
    int lastDigit = number % 10;
    int firstDigit = number / 10;
    if (lastDigit > 1) {
        return (firstDigit + 1) * (int)Math.pow(10, currentDigit - 1);
    } else if (lastDigit == 1) {
        return firstDigit * (int)Math.pow(10, currentDigit - 1) + countDigitOneRecursive(firstDigit * 10, currentDigit + 1);
    } else {
        return firstDigit * (int)Math.pow(10, currentDigit - 1);
    }
}

public static boolean isPowerOfTwo(int n) {
    if (n <= 0) {
        return false; // Non-positive integers cannot be powers of two
    }
    for (int i = 0; (1 << i) <= n; i++) {
        if ((1 << i) == n) {
            return true;
        }
    }
    return false;
}

public static boolean isPowerOfTwo(int n) {
    // Handle edge case where n is 0, as 0 is not a power of two
    if (n == 0) {
        return false;
    }
    // Check if n is a power of two by continuously dividing it by 2 until it is no longer divisible by 2
    while (n % 2 == 0) {
        n /= 2;
    }
    // If the loop completes and n equals 1, n was a power of two
    return n == 1;
}

