public static int longestLineRecursive(int[][] mat, int i, int j, int[][] directions) {
    int count = 1;
    for (int[] direction : directions) {
        int ti = i + direction[0], tj = j + direction[1];
        while (ti >= 0 && ti < mat.length && tj >= 0 && tj < mat[0].length && mat[ti][tj] == 1) {
            ti += direction[0];
            tj += direction[1];
            count++;
        }
    }
    return count;
}

public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return 0;
    }

    int rows = mat.length;
    int cols = mat[0].length;
    int maxLen = 0;

    // Horizontal and vertical lines
    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            if (mat[i][j] == 1) {
                int currentLen = 1;
                int temp = j;
                while (temp < cols && mat[i][temp] == 1) {
                    currentLen++;
                    temp++;
                }
                maxLen = Math.max(maxLen, currentLen);

                temp = j;
                while (temp >= 0 && mat[i][temp] == 1) {
                    currentLen++;
                    temp--;
                }
                maxLen = Math.max(maxLen, currentLen);
            }
        }
    }

    // Diagonal lines
    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            if (mat[i][j] == 1) {
                int currentLen = 1;
                int temp = i;
                int temp1 = j;
                while (temp < rows && temp1 < cols && mat[temp][temp1] == 1) {
                    currentLen++;
                    temp++;
                    temp1++;
                }
                maxLen = Math.max(maxLen, currentLen);

                temp = i;
                int temp2 = j;
                while (temp >= 0 && temp2 >= 0 && mat[temp][temp2] == 1) {
                    currentLen++;
                    temp--;
                    temp2--;
                }
                maxLen = Math.max(maxLen, currentLen);
            }
        }
    }

    // Anti-diagonal lines
    for (int i = 0; i < rows; i++) {
        for (int j = cols - 1; j >= 0; j--) {
            if (mat[i][j] == 1) {
                int currentLen = 1;
                int temp = i;
                int temp1 = j;
                while (temp < rows && temp1 >= 0 && mat[temp][temp1] == 1) {
                    currentLen++;
                    temp++;
                    temp1--;
                }
                maxLen = Math.max(maxLen, currentLen);

                temp = i;
                int temp2 = j;
                while (temp >= 0 && temp2 < cols && mat[temp][temp2] == 1) {
                    currentLen++;
                    temp--;
                    temp2++;
                }
                maxLen = Math.max(maxLen, currentLen);
            }
        }
    }

    return maxLen;
}

