    for (int i = 0; i < m - 1; i++) {
        int len = 0;
        for (int j = 0; j < n - 1; j++) {
            if (mat[i][j] == 1 && mat[i + 1][j + 1] == 1) {
                len++;
                maxLen = Math.max(maxLen, len);
            } else {
                len = 0;
            }
        }
    }

    // Checking anti-diagonals
    for (int i = 1; i < m - 1; i++) {
        int len = 0;
        for (int j = 0; j < n - 1; j++) {
            if (mat[i][j] == 1 && mat[i + 1][j - 1] == 1) {
