    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                lengthHorizontal(mat, i, j, maxLength);
                lengthVertical(mat, i, j, maxLength);
                lengthDiagonal(mat, i, j, maxLength);
                lengthAntiDiagonal(mat, i, j, maxLength);
            }
        }
    }

    return maxLength;
}

private static void lengthHorizontal(int[][] mat, int i, int j, int maxLength) {
    int length = 1;
