public static String addThousandSeparator(int n) {
    if (n < 0) {
        throw new IllegalArgumentException("Negative numbers are not supported");
    }

    if (n == 0) {
        return "0";
    }

    StringBuilder result = new StringBuilder();
    int count = 0;
    while (n > 0) {
        int digit = n % 10;
        if (count % 3 == 0 && count > 0) {
