public static int squarePermutations(int[] A) {
    int len = A.length;
    if (len == 0) return 0;

    // Sort the array to potentially simplify the search
    Arrays.sort(A);

    // Initialize the count of square permutations
    int count = 0;

    // Iterate through the array to form permutations
    for (int i = 0; i < len - 1; i++) {
        if (A[i] > A[i + 1] || A[i] * A[i] % 10 != 0) {
            // Skip dupe elements and invalid combinations
            continue;
        }
        int j = i + 1;
        while (j < len && A[j] * A[j] % 10 != 0) {
            j++;
        }
        // Skip repeat combinations
        if (j < len && A[j] == A[i]) {
            continue;
        }

        // Recursive permutation generation
        boolean[] visited = new boolean[len];
        Helper(A, i, j, visited, 0, count);
    }

    return count;
}

private static void Helper(int[] A, int i, int j, boolean[] visited, int perm, int[] count) {
    if (perm == visited.length) {
        count[0]++;
        return;
    }

    for (int k = i + 1; k < j; k++) {
        if (visited[k] || (k > i + 1 && !visited[k - 1] && A[k - 1] > A[k])) continue;

        visited[k] = true;
        Helper(A, i, j, visited, perm + 1, count);
        visited[k] = false;
    }
}

public static int squarePermutations(int[] A) {
    HashSet<Integer> used = new HashSet<>();
    int[][] visited = new int[A.length][A.length];
    return permute(A, used, visited, 0, 0, 0, -1);
}

private static int permute(int[] A, HashSet<Integer> used, int[][] visited, int indexStart, int indexR, int permCount, int prev) {
    int count = 0;
    for (int i = indexStart; i < A.length; i++) {
        if (indexStart - i == 1 && Math.pow(base(A[indexR]) - base(prev), 2) == 1) return 1;
        if (used.contains(A[i])) continue;
        int baseA = base(A[i]);
        // No way to swap baseA with any other number if its base is already used
        if (visited[indexR][i] == 1 || indexStart > i) continue;
        if (prev >= baseA || checkSquare(prev, baseA)) {
            visited[indexR][i] = 1;
            if (indexR == A.length - 1) {
                permCount++;
            } else {
                count += permute(A, used, visited, i + 1, indexR + 1, permCount, A[i]);
            }
            visited[indexR][i] = 0;
        }
        used.add(A[i]);
    }
    return count;
}

private static boolean checkSquare(int a, int b) {
    double diff = Math.sqrt(b - a);
    return diff == Math.ceil(diff);
}

