    for (int i = n; i > 0; i--) {
        int j = new Random().nextInt(i + 1);
        int temp = A[i];
        A[i] = A[j];
        A[j] = temp;

        if (isValidPermutation(A)) {
            count++;
        }
    }

    return count;
}

private static boolean isValidPermutation(int[] A) {
    // Check if adjacent elements have a perfect square sum
    for (int i = 0; i < A.length - 1; i++) {
        if (!isPerfectSquare(A[i] + A[i + 1])) {
            return false;
        }
    }
    return true;
}

