    int s = (int) Math.sqrt(x);
    return s * s == x;
}

public static int squarePermutations(int[] A) {
        if (A == null || A.length % 2 != 0) {
            throw new IllegalArgumentException("Input array must be non-empty and even-sized.");
        }

        int n = A.length;
        int[] dp = new int[n + 1];
        List<Integer> used = new ArrayList<>();
        for (int i = 0; i <= n; i++) {
            dp[i] = 0;
        }
        dp[0] = 1; // Base case: there's one permutation of length 0 (the empty array).

        for (int i = 0; i < n; i++) {
            used.add(A[i]);
            dp[n] += dp[n - A[i] * A[i]]; // Include the current permutation.
            if (used.contains(i)) {
                dp[n] -= dp[n - A[i] * A[i]]; // Exclude the current permutation if it was already used.
            }
            used.remove(i);
        }

        return dp[n];
    }

public static int squarePermutations(int[] A) {
        if (A == null || A.length == 0) {
            throw new IllegalArgumentException("Array must not be null or empty");
        }

        int n = A.length;
        List<List<Integer>> combinations = new ArrayList<>();
        boolean[] used = new boolean[n];

        backtrack(combinations, A, used, 0, n, 0);

        return combinations.size();
    }

private static void backtrack(List<List<Integer>> combinations, int[] A, boolean[] used, int start, int n, int length) {
        if (length == n) {
            return;
        }

        for (int i = start; i < n; i++) {
            if (used[i] && (i == 0 || !isPerfectSquare(A[i] + A[i - 1]))) {
                continue;
            }
            used[i] = true;
            backtrack(combinations, A, used, i + 1, n, length + 1);
            used[i] = false;
        }
    }

private static boolean isPerfectSquare(int num) {
        return num >= 1 && Math.sqrt(num) == Math.floor(Math.sqrt(num));
    }

public static int largestRectangleArea(int[] heights) {
    if (heights == null || heights.length == 0) {
        return 0;
    }

    int n = heights.length;
    int[] leftSmaller = new int[n];
    int[] rightSmaller = new int[n];

    // Find the nearest smaller element to the left of each element
    Stack<Integer> stack = new Stack<>();
    for (int i = 0; i < n; i++) {
        while (!stack.isEmpty() && heights[i] <= heights[stack.peek()]) {
            stack.pop();
        }
        if (stack.isEmpty()) {
            leftSmaller[i] = -1;
        } else {
            leftSmaller[i] = stack.peek();
        }
        stack.push(i);
    }

    // Clear the stack
    stack.clear();

    // Find the nearest smaller element to the right of each element
    for (int i = n - 1; i >= 0; i--) {
        while (!stack.isEmpty() && heights[i] <= heights[stack.peek()]) {
            stack.pop();
        }
        if (stack.isEmpty()) {
            rightSmaller[i] = n;
        } else {
            rightSmaller[i] = stack.peek();
        }
        stack.push(i);
    }

    int maxArea = 0;
    for (int i = 0; i < n; i++) {
        maxArea = Math.max(maxArea, heights[i] * (rightSmaller[i] - leftSmaller[i] - 1));
    }

    return maxArea;
}

