public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0) {
        return new int[0];
    }
    int m = mat.length, n = mat[0].length;
    int[] result = new int[m * n];
    int index = 0;
    int x = 0, y = 0;

    // Traverse the diagonals in a zigzag pattern
    while (index < m * n) {
        result[index++] = mat[x][y];
        if (x == 0 && y < n - 1) {
            y++;
        } else if (y == n - 1 && x < m - 1) {
            x++;
        } else if (x < m - 1 && y == 0) {
            x++;
        } else if (x == m - 1 && y < n - 1) {
            x--;
            y++;
        } else {
            x--;
            y--;
        }
    }

    return result;
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return new int[0];
    }

    int rows = mat.length;
    int cols = mat[0].length;
    int[] result = new int[rows * cols];
    int row = 0, col = 0;
    boolean isDown = true;

    while (row < rows && col < cols) {
        result[index++] = mat[row][col];

        if (isDown) {
            if (col == cols - 1) {
                row++;
            } else if (row == 0) {
                col++;
            } else {
                row--;
                col++;
            }
        } else {
            if (row == rows - 1) {
                col++;
            } else if (col == 0) {
                row++;
            } else {
                row++;
                col--;
            }
        }

        isDown = !isDown;
    }

    return result;
}

public static int[] diagonalOrder(int[][] mat) {
