    }

    int rows = mat.length;
    int cols = mat[0].length;
    int i = 0, j = 0;
    int[] result = new int[rows * cols];
    int index = 0;

    boolean up = true;

    while (index < result.length) {
        result[index++] = mat[i][j];
        if (up && j == cols - 1) {
            i++;
            up = false;
        } else if (!up && i == rows - 1) {
            j++;
            up = true;
        } else if (up && j < 0) {
            j++;
            up = false;
        } else if (!up && i < 0) {
            i++;
            up = true;
        } else if (up && j > cols - 1) {
            i++;
            up = false;
        } else if (!up && i > rows - 1) {
            j++;
            up = true;
        }
    }

    return result;
}

public static int[] diagonalOrder(int[][] mat) {
    int n = mat.length, m = mat[0].length;
    int[] result = new int[n * m];
    int r = 0, c = 0, v = 0;

    while (r < n && c < m) {
        result[v++] = mat[r][c];

        // Move to the next diagonal element
        if (r == c) { // If diagonally north-east, move right
            c++;
            if (c == m) { // If reached the end, move down
                r++;
                if (r == n) break;
            }
        } else if (r > c) { // If diagonally north-west, move left
            r--;
            if (r == -1) { // If reached the top, move down
                r++;
                if (r == n) break;
            }
            c++;
        } else { // If diagonally south-west, move up
            c--;
            if (c == -1) { // If reached the left, move right
                c++;
                r++;
                if (r == n) break;
            }
            r--;
        }
    }

    return result;
}

public static int[] diagonalOrder(int[][] mat) {
    int yMax = mat.length - 1;
    int zMax = mat[0].length - 1;

    if (yMax < 0 || zMax < 0) {
        throw new IllegalArgumentException("Matrix is too small or empty!");
    }

    int[] outMatrix = new int[yMax + zMax + 1];
    int outIdx = 0;

    // Moving all left tête horizontale
    for (int y = 0, z = 0; z <= zMax; z++) {
        moveColumn(mat, y, z, outIdx, outMatrix);
        if (yMax < y) {
            break;
        }
    }

    // Moving all tête verticale
    for (int y = 0, x = 0; x <= xMax; x++) {
        moveRow(mat, y, x, outIdx, outMatrix);
        if (zMax < y) {
            break;
        }
    }

    return outMatrix;
}

private static void moveColumn(int[][] mat, int y, int z, int outIdx, int[] outMatrix) {
    outMatrix[outIdx++] = mat[y][z];

    for (; y < yMax; y++) {
        if (z < zMax) {
            outMatrix[outIdx++] = mat[y][z + 1];
        } else {
            outMatrix[outIdx++] = mat[y][0];
        }
    }
}

private static void moveRow(int[][] mat, int y, int x, int outIdx, int[] outMatrix) {
    outMatrix[outIdx++] = mat[y][x];

    for (; x < xMax; x++) {
        if (y < yMax) {
            outMatrix[outIdx++] = mat[y + 1][x];
        } else {
            outMatrix[outIdx++] = mat[0][x];
        }
    }
}

public static int findSmallestInteger(int n) {
    if (n <= 1) {
        return -1; // No positive integer greater than 1 can be formed by rearranging its digits.
    }

    // Convert the integer to a character array.
    char[] digits = String.valueOf(n).toCharArray();

    // Bubble sort the digits in descending order.
    for (int i = 0; i < digits.length; i++) {
        for (int j = i + 1; j < digits.length; j++) {
            if (digits[i] < digits[j]) {
                // Swap the digits.
                char temp = digits[i];
                digits[i] = digits[j];
                digits[j] = temp;
            }
        }
    }

    // Check if the resulting string can be converted back to an integer.
    // If not, return -1.
    try {
        int smallestNumber = Integer.parseInt(new String(digits));
        // Check if the smallest number is greater than the input number.
        if (smallestNumber > n) {
            return smallestNumber;
        }
    } catch (NumberFormatException e) {
        return -1; // Invalid number format, return -1.
    }

    // Return -1 if no valid rearrangements can form a number greater than the input number.
    return -1;
}

public static int findSmallestInteger(int n) {
    // Convert the integer to a character array to manipulate the digits
    char[] digits = String.valueOf(n).toCharArray();
    int find = digits.length;
    // Iterate through the digits to find the smallest digit (not equal to n)
    for (int i = find - 1; i > 0; i--) {
        if (digits[i] > digits[i - 1]) {
            // Find the largest digit that is greater than digits[i - 1]
            for (int j = find - 1; j >= 0; j--) {
                if (digits[j] > digits[i - 1]) {
                    // Swap digits[i - 1] and digits[j]
                    char temp = digits[i - 1];
                    digits[i - 1] = digits[j];
                    digits[j] = temp;
                    // Sort the digits after digits[i - 1]
                    Arrays.sort(digits, i, find);
                    // Convert back to integer and return
                    return Integer.parseInt(String.valueOf(digits));
                }
            }
        }
    }
    // Return -1 if no such rearranged integer is possible
    return -1;
}

