            if (digits[j] > digits[i]) {
                char temp = digits[i];
                digits[i] = digits[j];
                digits[j] = temp;
                Arrays.sort(digits, i + 1, digits.length);
                StringBuilder sb = new StringBuilder();
                for (char digit : digits) {
                    sb.append(digit);
                }
                return Integer.parseInt(sb.toString());
            }
        }
    }
    return -1;
}

public static int findSmallestInteger(int n) {
    String num = String.valueOf(n);
    int length = num.length();

    // Check if there are no conditions for swapping to form a smaller number
    if (num.charAt(0) == '9') {
        return -1;
    }

    // Find the first digit after '9' from the end, which can be swapped to form a smaller number
    int idx = length - 2;
    while (idx >= 0 && num.charAt(idx) <= '8') {
        idx--;
    }

    if (idx == -1) {
        return -1; // No valid rearrangement possible
    }

    // Swap the found digit with the first digit after '9'
    char temp = num.charAt(idx);
    num = num.substring(0, idx) + num.charAt(length - 1) + num.substring(idx + 1, length - 1) + temp;

    // Convert the modified string back to an integer
    return Integer.parseInt(num);
}

public static int findSmallestInteger(int n) {
    boolean modified = false;
    for (int i = (int) Math.pow(10, n.toString().length()); i > 0; i--) {
        int temp = i;
        while (temp != 0) {
            int digit = temp % 10;
            if (digit < n) {
                if (!modified) {
                    n = digit;
                    modified = true;
                } else {
                    return -1; // More than one digit needs to be changed
                }
            }
            temp /= 10;
        }
    }
    return n == 0 ? -1 : n; // No valid rearrangement found
}

