public static boolean isBoomerang(int[][] points) {
    if (points.length != 3) {
        throw new IllegalArgumentException("Exactly 3 points are required");
    }

    int x1 = points[0][0], y1 = points[0][1];
    int x2 = points[1][0], y2 = points[1][1];
    int x3 = points[2][0], y3 = points[2][1];

    // Check if any point is the same as any other point
    if (x1 == x2 || x1 == x3 || y1 == y2 || y1 == y3) {
        return false;
    }

    // Check if the points form a non-degenerate triangle (area formula not needed, but to avoid division by zero)
    // If the points are on the same line, there will be side length of 0
    double slope1 = (y2 - y1) / (x2 - x1);
    double slope2 = (y3 - y2) / (x3 - x2);
    double slope3 = (y1 - y3) / (x1 - x3);

    return !Math.abs(slope1 - slope2) <= 1e-9 && !Math.abs(slope2 - slope3) <= 1e-9;
}

public static boolean isBoomerang(int[][] points) {
    if (points.length != 3) {
        throw new IllegalArgumentException("Input array must contain exactly three points.");
    }
    int x1 = points[0][0], y1 = points[0][1];
    int x2 = points[1][0], y2 = points[1][1];
    int x3 = points[2][0], y3 = points[2][1];

    // Check if any set of three points are collinear by calculating the area of the triangle formed by them.
    if ((y3 - y1) * (x2 - x1) == (x3 - x1) * (y2 - y1)) {
        return false;
    }

    // A boomerang is formed if the points are not collinear.
    return true;
}

public static boolean isBoomerang(int[][] points) {
