private static boolean isTriangle(int[] p1, int[] p2, int[] p3) {
    int[] dx1 = {p2[0] - p1[0], p3[0] - p1[0]};
    int[] dy1 = {p2[1] - p1[1], p3[1] - p1[1]};

    int[] dx2 = {p3[0] - p2[0], p1[0] - p2[0]};
    int[] dy2 = {p3[1] - p2[1], p1[1] - p2[1]};

    return (dx1[0] * dy1[1] - dy1[0] * dx1[1]) != (dx2[0] * dy2[1] - dy2[0] * dx2[1]);
}

public static int findNthUglyNumber(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("Input must be a positive integer");
    }

    if (DP[n][3] > 0) {
        return DP[n][3];
    }

    int i0 = 0, i1 = 0, i2 = 0;
    int indices[] = {i0, i1, i2};
    int[] nums = {2, 3, 5};

    for (int i = 1; i <= n; i++) {
        int nouvelleValeur = Math.min(nums[0], Math.min(nums[1], nums[2]));
        DP[i][0] = DP[i-1][0] + (DP[i][3] == 0 ? 1 : 0);
        DP[i][1] = nouvelleValeur;
        indices[nums.indexOf(nouvelleValeur)]++;
        nums[nums.indexOf(nouvelleValeur)] *= 2;
    }

    return DP[n][1];
}

public static int findNthUglyNumber(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("Input should be a positive integer.");
    }
    boolean[] isUgly = new boolean[n + 1];
    isUgly[1] = true;
    int[] factors = {2, 3, 5};

    // Initialize pointers for the three factors
    int firstFactorPointer = 0, secondFactorPointer = 0, thirdFactorPointer = 0;

    for (int i = 2; i <= n; i++) {
        int nextUgly = Math.min(isUgly[firstFactorPointer] * factors[0], Math.min(isUgly[secondFactorPointer] * factors[1], isUgly[thirdFactorPointer] * factors[2]));
        isUgly[i] = (nextUgly != isUgly[i - 1]);

        // Update the pointers for the factors
        if (nextUgly == isUgly[firstFactorPointer] * factors[0]) firstFactorPointer++;
        if (nextUgly == isUgly[secondFactorPointer] * factors[1]) secondFactorPointer++;
        if (nextUgly == isUgly[thirdFactorPointer] * factors[2]) thirdFactorPointer++;
    }

    return isUgly[n];
}

public static int findNthUglyNumber(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("Input must be a positive integer");
    }

    int uglyThis = 1;
    int count = 1;
    int[] nextArr = new int[] {2, 3, 5};

    while (count < n) {
        int min = nextArr[0];
        for (int i = 1; i < nextArr.length; i++) {
            min = Math.min(min, nextArr[i]);
        }
        uglyThis = min;
        for (int i = 0; i < nextArr.length; i++) {
            if (nextArr[i] == uglyThis) {
                nextArr[i] = nextNext(nextArr, i);
                break;
            }
        }
        count++;
    }

    return uglyThis;
}

private static int nextNext(int[] arr, int index) {
    int min = arr[index];
    for (int i = index + 1; i < arr.length; i++) {
        min = Math.min(min, arr[i]);
    }
    return min * 2;
}

public static int findNthUglyNumber(int n) {
    PriorityQueue<Integer> priorityQueue = new PriorityQueue<>();
    priorityQueue.offer(2);
    priorityQueue.offer(3);
    priorityQueue.offer(5);

    Set<Integer> seen = new HashSet<>();
    seen.add(2);
    seen.add(3);
    seen.add(5);

    while (n > 0) {
        int current = priorityQueue.poll();
        if (n == 1) {
            return current;
        }

        priorityQueue.offer(current * 2);
        priorityQueue.offer(current * 3);
        priorityQueue.offer(current * 5);

        while (priorityQueue.peek() == current) {
            priorityQueue.poll();
        }

        n--;
    }

    return -1; // In case there is no nth ugly number
}

public static int findNthUglyNumber(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("Input must be a positive integer.");
    }

    int[] factors = {2, 3, 5};
    int[] minNumbers = new int[n];
    minNumbers[0] = 1;
    for (int i = 1; i < n; i++) {
        int minUgly = Integer.MAX_VALUE;
        for (int factor : factors) {
            int currentUgly = minNumbers[(i - 1) / factor] * factor;
            if (currentUgly < minUgly) {
                minUgly = currentUgly;
            }
        }
        minNumbers[i] = minUgly;
    }
    return minNumbers[n - 1];
}

