public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    if (n < 1) {
        return result; // Return an empty list for non-positive input
    }

    // Create a priority queue to maintain the numbers in lexicographical order
    PriorityQueue<Integer> queue = new PriorityQueue<>();
    // Initialize the queue with the smallest number
    queue.offer(1);

    while (!queue.isEmpty()) {
        int current = queue.poll();
        result.add(current); // Add the current number to the result list

        // Check if the current number can be multiplied by and added to (10 * current) to get a new number within the range
        if (current * 10 <= n) {
            queue.offer(current * 10); // Add the new number to the queue
        }

        // Check if the current number can be incremented by 1 to get a new number within the range
        if (current + 1 <= n) {
            queue.offer(current + 1); // Add the new number to the queue
        }
    }

    return result;
}

public static List<Integer> lexicalOrder(int n) {
        List<Integer> result = new ArrayList<>();
        for (int i = 1; i < 10; i++) {
            helper(result, i, n);
        }
        return result;
    }

private static void helper(List<Integer> result, int num, int n) {
        if (num <= n) {
            result.add(num);
            for (int i = 0; i < 10; i++) {
                helper(result, num * 10 + i, n);
            }
        }
    }

public static List<Integer> lexicalOrder(int n) {
        List<Integer> result = new ArrayList<>();
        helper(1, range, 0, result);
        return result;
    }

private static void helper(long num, long r, long offset, List<Integer> result) {
        if (num > range) {
            return;
        }
        result.add((int) num);
        helper(num * 10, r, offset + 1, result); // 移动到十位继续
        if (r <= offset) {
            helper(num + 1, range, 0, result); // 循环移到个位继续
        }
    }

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new java.util.ArrayList<>();
    if (n <= 0) {
        return result;
    }

    dfs(result, 1, n);
    return result;
}

private static void dfs(List<Integer> result, int cur, int n) {
    result.add(cur);
    for (int i = 0; i <= 9; ++i) {
        if (cur * 10 + i <= n) {
            dfs(result, cur * 10 + i, n);
        } else {
            break;
        }
    }
}

