public static int minPerfectSquareSum(int n) {
    if (n < 1) {
        throw new IllegalArgumentException("n must be a positive integer");
    }

    int limit = (int) Math.sqrt(n);
    int[] dp = new int[n + 1];
    Arrays.fill(dp, Integer.MAX_VALUE);
    dp[0] = 0;

    for (int i = 1; i <= limit; i++) {
        int square = i * i;
        for (int j = square; j <= n; j++) {
            dp[j] = Math.min(dp[j], dp[j - square] + 1);
        }
    }

    return dp[n];
}

public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("Input must be a positive integer.");
    }

    // Initialize an array to store the minimum number of perfect squares needed for each sum up to n
    int[] dp = new int[n + 1];
    Arrays.fill(dp, Integer.MAX_VALUE);
    dp[0] = 0; // Base case: to reach sum 0, the number of perfect squares required is 0

    // Fill the dp array
    for (int i = 1; i <= n; i++) {
        int sqrt = (int) Math.sqrt(i);
        for (int j = 1; j <= sqrt; j++) {
            dp[i] = Math.min(dp[i], dp[i - j * j] + 1);
        }
    }

    return dp[n];
}

public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
        return 0;
    }

    int[] dp = new int[n + 1];
    dp[0] = 0;

    for (int num = 1; num <= n; num++) {
        int min = Integer.MAX_VALUE;
        for (int i = 1, square = 1; i * square <= num; i++, square = i * i) {
            min = Math.min(min, dp[num - square] + 1);
        }
        dp[num] = min;
    }

    return dp[n];
}

public static int minPerfectSquareSum(int n) {
    // Dynamic programming approach to find the minimum number of perfect squares that sum up to n
    int[] dp = new int[n + 1];
    Arrays.fill(dp, Integer.MAX_VALUE);
    dp[0] = 0;

    for (int i = 1; i <= n; i++) {
        for (int j = 1; j * j <= i; j++) {
            dp[i] = Math.min(dp[i], dp[i - j * j] + 1);
        }
    }

    return dp[n];
}

public static int minPerfectSquareSum(int n) {
        int maxSquareRoot = (int) Math.sqrt(n);
        int[] dp = new int[n + 1];

        // Base case: two 1s can sum up to the number itself
        Arrays.fill(dp, 2);

        // Fill the dp array
        for (int i = 1; i <= maxSquareRoot; i++) {
            long square = (long) i * i;
            for (int j = square; j <= n; j++) {
                dp[j] = Math.min(dp[j], dp[j - square] + 1);
            }
        }

        // The result is dp[n]
        return dp[n];
    }

public static String reverseWords(String s) {
    if (s == null || s.isEmpty()) {
        throw new IllegalArgumentException("Input string cannot be null or empty.");
    }

    String[] words = s.split("\\s+");
    for (int i = 0; i < words.length; i++) {
        StringBuilder reversedWord = new StringBuilder(words[i]);
        int left = 0, right = reversedWord.length() - 1;
        while (left < right) {
            char temp = reversedWord.charAt(left);
            reversedWord.setCharAt(left, reversedWord.charAt(right));
            reversedWord.setCharAt(right, temp);
            left++;
            right--;
        }
        words[i] = reversedWord.toString();
    }

    return String.join(" ", words);
}

public static String reverseWords(String s) {
    if (s == null || s.isEmpty()) {
        return "";
    }

    String[] words = s.split("\\s+");
    StringBuilder result = new StringBuilder();

    for (String word : words) {
        if (word != null) {
            String reversedWord = new StringBuilder(word).reverse().toString();
            result.append(reversedWord).append(" ");
        }
    }

    return result.toString().trim();
}

public static String reverseWords(String s) {
    if (s == null || s.isEmpty()) {
        return s;
    }

    String[] words = s.split(" ");
    StringBuilder result = new StringBuilder();

    for (String word : words) {
        char[] charArray = word.toCharArray();
        for (int i = 0, j = charArray.length - 1; i < j; i++, j--) {
            char temp = charArray[i];
            charArray[i] = charArray[j];
            charArray[j] = temp;
        }

        result.append(charArray).append(" ");
    }

    return result.toString().trim();
}

public static String reverseWords(String s) {
    StringBuilder sb = new StringBuilder();
    String[] words = s.split(" ");

    for (String word : words) {
        // Reverse the characters of the word and append it to the result
        sb.append(new StringBuilder(word).reverse().toString());
        // Append a space unless it's the last word
        if (words.length > 1) {
            sb.append(" ");
        }
    }

    return sb.toString();
}

public static String reverseWords(String s) {
    if (s == null || s.isEmpty()) {
        return s;
    }

    String[] words = s.split(" ");
    StringBuilder result = new StringBuilder();

    for (String word : words) {
        StringBuilder reversedWord = new StringBuilder();
        for (int i = word.length() - 1; i >= 0; i--) {
            reversedWord.append(word.charAt(i));
        }
        result.append(reversedWord).append(" ");
    }

    return result.toString().trim();
}
